package com.sakalti.modifier;
import net.minecraft.world.effect.*; import net.minecraft.world.entity.LivingEntity; import slimeknights.tconstruct.library.modifiers.Modifier; import slimeknights.tconstruct.library.tools.context.ToolAttackContext; import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
public class HeavyStoneModifier extends Modifier { @Override public int afterEntityHit(IToolStackView tool,int level,ToolAttackContext ctx,float damage){LivingEntity a=ctx.getAttacker();if(a!=null&&!a.level().isClientSide){a.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,100,4));a.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE,100,2));}return 0;}}
